    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for c in row:
            counts[c] = counts.get(c, 0) + 1
    background = max(counts, key=counts.get)
    # Divider color forms complete separator row/columns. Copy the marked tile pattern
    # into every tile, retaining separator lines.
    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != background]
    sep_cols = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h)) and grid[0][c] != background]
    row_bands = []
    a = 0
    for r in sep_rows:
        if a < r: row_bands.append((a, r))
        a = r + 1
    if a < h: row_bands.append((a, h))
    col_bands = []
    a = 0
    for c in sep_cols:
        if a < c: col_bands.append((a, c))
        a = c + 1
    if a < w: col_bands.append((a, w))
    if len(row_bands) < 2 or len(col_bands) < 2:
        return grid
    # Locate tile with the most non-background cells as the source pattern.
    source = max(((sum(grid[r][c] != background for r in range(ra, rb) for c in range(ca, cb)), ra, rb, ca, cb)
                  for ra, rb in row_bands for ca, cb in col_bands), key=lambda x: x[0])
    _, ra, rb, ca, cb = source
    rh, cw = rb-ra, cb-ca
    out = [row[:] for row in grid]
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    sr, sc = ra + (r-r0) % rh, ca + (c-c0) % cw
                    out[r][c] = grid[sr][sc]
    return out
